from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def rw(path, fn):
    p=ROOT/path
    text=p.read_text(encoding="utf-8")
    new=fn(text)
    if new==text:
        raise SystemExit(f"no change for {path}")
    p.write_text(new,encoding="utf-8")

# Release/cache bump. Keep old release documentation untouched.
for path in [ROOT/"app.js",ROOT/"index.html",*sorted((ROOT/"src").glob("*.js")),*sorted((ROOT/"api").glob("*.js")),*sorted((ROOT/"test").glob("*.js"))]:
    text=path.read_text(encoding="utf-8")
    new=text.replace("57019","57020")
    if new!=text:path.write_text(new,encoding="utf-8")

rw(Path("package.json"),lambda s:s.replace('"version": "0.57.19"','"version": "0.57.20"'))
rw(Path("src/version.js"),lambda s:s.replace('APP_VERSION="0.57.19"','APP_VERSION="0.57.20"'))
for rel in [Path("test/version-0551-release.test.js"),Path("test/version-ui.test.js")]:
    p=ROOT/rel
    text=p.read_text(encoding="utf-8")
    new=text.replace("0.57.19","0.57.20").replace(r"0\\.57\\.19",r"0\\.57\\.20")
    if new!=text:p.write_text(new,encoding="utf-8")

p=ROOT/"src/contextual-actions.js"
s=p.read_text(encoding="utf-8")
s=s.replace(
'const PROGRESSION_EVENT_TYPES=new Set(["WORLD_EVENT","WORLD_CONSEQUENCE","WORLD_CONSEQUENCE_DISCOVERED","RUMOR_SPREAD","PLAYER_RECOGNITION","FACTION_PLAYER_REACTION","WEATHER_CHANGED","FUTURE_EVENT_TRIGGERED","MAIN_QUEST_STAGE_CHANGED","NPC_CLUE_CONFIRMED"]);',
'const PROGRESSION_EVENT_TYPES=new Set(["WORLD_EVENT","WORLD_CONSEQUENCE","WORLD_CONSEQUENCE_DISCOVERED","RUMOR_SPREAD","PLAYER_RECOGNITION","FACTION_PLAYER_REACTION","WEATHER_CHANGED","FUTURE_EVENT_TRIGGERED","NPC_CLUE_CONFIRMED"]);\nconst OBSERVABLE_PROGRESS_CUE=/(?:看見|看到|聽見|聽到|傳來|響起|發出|散發|留下|出現|消失|停止|恢復|打開|關閉|封鎖|開放|移動|離開|靠近|遠去|倒下|破損|坍塌|燃燒|閃爍|震動|逐漸|變得|嗡鳴|敲擊|腳步|痕跡|足跡|裂痕|血跡|煙|火光|霧|雨|雪|符號|輪廓)/;\nconst QUEST_PROGRESS_META=/(?:任務|主線|支線|目標|階段|委託|進度|建立第一段關係|完成條件)/;')
needle='function eventMatchesCurrentScope(state,event){const currentWorld=String(state.world?.id||""),eventWorld=String(event?.worldId||"");if(eventWorld&&currentWorld&&eventWorld!==currentWorld)return false;const worldCreated=Number(state.world?.createdAt)||0,eventAt=Number(event?.at)||0;if(!eventWorld&&worldCreated&&eventAt&&eventAt<worldCreated)return false;const loc=currentLocationRecord(state),scope=String(event?.locationId||event?.location||"");if(scope){const allowed=new Set([String(state.player?.location||""),String(loc?.id||""),String(loc?.name||"")].filter(Boolean));if(!allowed.has(scope))return false}return true}\nfunction recentVisibleEvent(state){return (state.events||[]).filter(e=>e?.visibility!=="INTERNAL"&&PROGRESSION_EVENT_TYPES.has(String(e.type||""))&&eventMatchesCurrentScope(state,e)).map(e=>({...e,summary:playerFacingEventSummary(e)})).filter(e=>e.summary).slice(-8).reverse()[0]||null}\nfunction recentNpcClue(state){return (state.events||[]).filter(e=>String(e?.type||"")==="NPC_CLUE_CONFIRMED"&&e?.visibility!=="INTERNAL"&&eventMatchesCurrentScope(state,e)).map(e=>({...e,summary:playerFacingEventSummary(e)})).filter(e=>e.summary).slice(-6).reverse()[0]||null}'
replacement='function eventMatchesCurrentScope(state,event){const currentWorld=String(state.world?.id||""),eventWorld=String(event?.worldId||"");if(eventWorld&&currentWorld&&eventWorld!==currentWorld)return false;const worldCreated=Number(state.world?.createdAt)||0,eventAt=Number(event?.at)||0;if(!eventWorld&&worldCreated&&eventAt&&eventAt<worldCreated)return false;const loc=currentLocationRecord(state),scope=String(event?.locationId||event?.location||"");if(scope){const allowed=new Set([String(state.player?.location||""),String(loc?.id||""),String(loc?.name||"")].filter(Boolean));if(!allowed.has(scope))return false}return true}\nfunction eventHasCurrentSceneProvenance(state,event){const loc=currentLocationRecord(state),scope=String(event?.locationId||event?.location||"");if(!scope)return false;const allowed=new Set([String(state.player?.location||""),String(loc?.id||""),String(loc?.name||"")].filter(Boolean));return allowed.has(scope)}\nfunction questReferenceTexts(state){const main=state.quests?.main||{},side=state.world?.registry?.sideQuests||[];return [main.title,main.aiHint,...(main.objectives||[]),...side.flatMap(q=>[q?.title,q?.objective])].map(x=>clean(x,180)).filter(x=>x.length>=6)}\nfunction summaryLooksLikeQuestProgress(state,summary){const text=clean(summary,220);if(!text)return true;if(QUEST_PROGRESS_META.test(text))return true;return questReferenceTexts(state).some(ref=>text===ref||text.startsWith(ref+"：")||text.startsWith(ref+":")||text.startsWith(ref+"。"))}\nfunction eventHasConcreteObservableContent(state,event,summary){if(!eventHasCurrentSceneProvenance(state,event))return false;if(String(event?.type||"")==="NPC_CLUE_CONFIRMED")return Boolean(summary);if(summaryLooksLikeQuestProgress(state,summary))return false;return OBSERVABLE_PROGRESS_CUE.test(summary)}\nfunction recentVisibleEvent(state){return (state.events||[]).filter(e=>e?.visibility!=="INTERNAL"&&PROGRESSION_EVENT_TYPES.has(String(e.type||""))&&eventMatchesCurrentScope(state,e)).map(e=>({...e,summary:playerFacingEventSummary(e)})).filter(e=>e.summary&&eventHasConcreteObservableContent(state,e,e.summary)).slice(-8).reverse()[0]||null}\nfunction recentNpcClue(state){return (state.events||[]).filter(e=>String(e?.type||"")==="NPC_CLUE_CONFIRMED"&&e?.visibility!=="INTERNAL"&&eventMatchesCurrentScope(state,e)&&eventHasCurrentSceneProvenance(state,e)).map(e=>({...e,summary:playerFacingEventSummary(e)})).filter(e=>e.summary).slice(-6).reverse()[0]||null}'
if needle not in s:raise SystemExit("contextual-actions scope block not found")
s=s.replace(needle,replacement)
p.write_text(s,encoding="utf-8")

test=(ROOT/"test/v05720-observable-progression.test.js")
test.write_text('''import test from "node:test";\nimport assert from "node:assert/strict";\nimport {regenerateContextualActionSet} from "../src/contextual-actions.js";\n\nfunction state(){return {world:{id:"W20",createdAt:1000,state:{day:1},registry:{locations:[{id:"L1",name:"石橋",known:true}],npcs:[],sideQuests:[]},creation:{blueprint:{difficulty:"normal"}}},player:{location:"石橋",difficulty:"normal",skills:{OBSERVE:1,SOCIAL:1,TRAVEL:0,RISKY:0},magic:{knownSpells:[]}},quests:{main:{title:"在異世界建立第一段關係",objectives:["找到可以交流的人，理解這裡的人如何生活。"],status:"ACTIVE"}},events:[]}}\nfunction text(set){return set.all.map(x=>x.label+" "+x.action).join("\\n")}\n\ntest("v0.57.20 quest title/status events are never presented as observable progression evidence",()=>{\n const s=state();const questText="在異世界建立第一段關係：找到可以交流的人，理解這裡的人如何生活。";\n s.events.push({id:"Q1",type:"MAIN_QUEST_STAGE_CHANGED",visibility:"PLAYER_KNOWN",worldId:"W20",location:"石橋",summary:questText,at:1200});\n s.events.push({id:"Q2",type:"WORLD_CONSEQUENCE",visibility:"PLAYER_KNOWN",worldId:"W20",location:"石橋",summary:questText,at:1300});\n const out=text(regenerateContextualActionSet(s));\n assert.doesNotMatch(out,/沿著最近事件|造成的可見影響/);assert.doesNotMatch(out,/在異世界建立第一段關係：/);assert.match(out,/石橋|觀察|尋找|檢查|探索/)\n});\n\ntest("v0.57.20 progression events require current-scene provenance",()=>{\n const s=state();\n s.events.push({id:"UNSCOPED",type:"WORLD_CONSEQUENCE",visibility:"PLAYER_KNOWN",worldId:"W20",summary:"北側鐘聲突然停止，遠處傳來金屬敲擊聲。",at:1200});\n s.events.push({id:"OTHER",type:"WORLD_CONSEQUENCE",visibility:"PLAYER_KNOWN",worldId:"W20",location:"L2",summary:"另一區域的鐵門突然關閉。",at:1300});\n const out=text(regenerateContextualActionSet(s));assert.doesNotMatch(out,/北側鐘聲|另一區域的鐵門|沿著最近事件/)\n});\n\ntest("v0.57.20 concrete observable event in the current scene may drive progression",()=>{\n const s=state();s.events.push({id:"OBS",type:"WORLD_CONSEQUENCE",visibility:"PLAYER_KNOWN",worldId:"W20",location:"石橋",summary:"北側鐵門突然關閉，門縫傳來反覆敲擊聲。",at:1400});\n const out=text(regenerateContextualActionSet(s));assert.match(out,/北側鐵門|敲擊聲/);assert.match(out,/沿著最近事件|追查/)\n});\n''',encoding="utf-8")

release=ROOT/"docs/releases/v0.57.20.md"
release.write_text('''# Elyndra v0.57.20\n\n- Progression suggestions only quote concrete, player-visible events with current-world/current-scene provenance.\n- Quest titles, quest-stage/status events, and abstract objectives are not treated as observable event evidence.\n- Unscoped or wrong-scene events fall back to direct observation, exploration, or available social actions instead of fabricated “visible effects”.\n- Adds non-download regressions for quest-title leakage, scene provenance, and valid observable-event progression.\n''',encoding="utf-8")
